function classifyExecutionFailure(
	cause: unknown,
	executionSignal: AbortSignal,
	deadline: number,
	deadlineTriggered = false,
): ExecutionFailureState {
	const attemptTimedOut = isAbortLike(cause) && !executionSignal.aborted;
	const deadlineExceeded =
		deadlineTriggered ||
